// Idempotency-Key for POST — making a non-idempotent create safe to retry
const { createHash, randomUUID } = require('node:crypto');

const store = new Map(); // key -> { fingerprint, status: 'pending' | 'done', response }
let orders = 0;

function fingerprint(body) {
  return createHash('sha256').update(JSON.stringify(body)).digest('hex');
}

async function handlePostOrders(headers, body) {
  const key = headers['idempotency-key'];
  if (!key) return { status: 400, body: { error: 'Idempotency-Key header required' } };

  const fp = fingerprint(body);
  const seen = store.get(key);
  if (seen) {
    if (seen.fingerprint !== fp) return { status: 422, body: { error: 'Key reused with a different body' } };
    if (seen.status === 'pending') return { status: 409, body: { error: 'Original request still in progress' } };
    return seen.response; // replay the stored response — no second order
  }

  // Claim the key BEFORE doing the work (in production: INSERT ... ON CONFLICT DO NOTHING,
  // or Redis SET key value NX EX 86400) so two concurrent retries cannot both proceed.
  store.set(key, { fingerprint: fp, status: 'pending' });
  const response = { status: 201, body: { orderId: ++orders, amount: body.amount } };
  store.set(key, { fingerprint: fp, status: 'done', response });
  return response;
}

(async () => {
  const key = randomUUID(); // generated ONCE per logical operation, reused on every retry
  const first = await handlePostOrders({ 'idempotency-key': key }, { amount: 50 });
  const retry = await handlePostOrders({ 'idempotency-key': key }, { amount: 50 });
  console.log(first.status, first.body); // 201 { orderId: 1, amount: 50 }
  console.log(retry.status, retry.body); // 201 { orderId: 1, amount: 50 }  (replayed)
  console.log('orders created:', orders); // 1
  const misuse = await handlePostOrders({ 'idempotency-key': key }, { amount: 99 });
  console.log(misuse.status); // 422
})();

