// REST vs GraphQL — side-by-side fetch patterns in JavaScript

// --- REST: multiple round-trips for related data ---
async function getUserWithOrdersREST(userId) {
  // First call: get the user
  const user = await fetch(`/v1/users/${userId}`).then(r => r.json());
  // Second call: under-fetching forces a second request
  const orders = await fetch(`/v1/users/${userId}/orders`).then(r => r.json());
  // Third call: loyalty data lives on a different service
  const loyalty = await fetch(`/v1/loyalty/users/${userId}`).then(r => r.json());
  // Assembled client-side from 3 independent requests
  return { ...user, orders, loyaltyPoints: loyalty.points };
}

// --- GraphQL: one request, exactly the fields needed ---
async function getUserWithOrdersGQL(userId) {
  const query = `
    query GetUserProfile($id: ID!) {
      user(id: $id) {
        name
        email
        orders {
          id
          total
          status
        }
        loyaltyAccount {
          points
          tier
        }
      }
    }
  `;
  const res = await fetch('/graphql', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ query, variables: { id: userId } }),
  });
  const { data } = await res.json();
  return data.user; // one trip, exact shape, no extra fields
}

// --- REST cursor pagination — stable across concurrent inserts ---
async function fetchOrdersCursor(userId, after = null) {
  const params = new URLSearchParams({ limit: '20' });
  if (after) params.set('after', after);
  const url = `/v1/users/${userId}/orders?${params}`;
  const { data, meta } = await fetch(url).then(r => r.json());
  // meta.next_cursor is null when we have reached the last page
  return { items: data, nextCursor: meta.next_cursor };
}

// user.proto — complete gRPC service definition (Protobuf 3)
syntax = "proto3";

package user.v1;

option go_package = "github.com/example/gen/user/v1";

// Import well-known types for timestamps
import "google/protobuf/timestamp.proto";

// UserService defines all RPCs for user management.
// The schema IS the contract — protoc generates type-safe
// client + server stubs in Go, Java, Python, TypeScript...
service UserService {
  // Unary: single request, single response
  rpc GetUser(GetUserRequest) returns (UserResponse);

  // Server streaming: client sends one request,
  // server pushes multiple OrderResponse messages over time
  rpc StreamOrders(StreamOrdersRequest) returns (stream OrderResponse);

  // Bidirectional streaming: live chat or collaborative editing
  rpc ChatSession(stream ChatMessage) returns (stream ChatMessage);
}

message GetUserRequest {
  // Field number 1 is forever bound to 'id'.
  // Never reuse a field number — old clients decode by number.
  int64 id = 1;
}

message UserResponse {
  int64  id         = 1;
  string name       = 2;
  string email      = 3;
  // New optional field added in v1.1 — old clients safely ignore it.
  // Old clients still parse field 1, 2, 3 correctly.
  string avatar_url = 4;
  google.protobuf.Timestamp created_at = 5;

  // Field 6 was deleted. Reserve it to prevent accidental reuse.
  reserved 6;
  reserved "old_phone_field";
}

message StreamOrdersRequest {
  int64  user_id    = 1;
  // Cursor token for resumable streaming
  string page_token = 2;
}

message OrderResponse {
  int64  id     = 1;
  double total  = 2;
  string status = 3;
}

message ChatMessage {
  string sender_id = 1;
  string content   = 2;
  google.protobuf.Timestamp sent_at = 3;
}
